std::array<uint8_t, 112> ldpc_encode(const std::array<uint8_t, 56>& s)
{
    // r = H_a * s  (mod 2)
    uint8_t r[56] = {};
    for (int i = 0; i < 56; ++i)
        for (int j = 0; j < 56; ++j)
            r[i] ^= H_a[i][j] & s[j];

    // Solve H_b * p = r by forward substitution.
    // H_b is lower-bidiagonal: H_b[0][0]=1; H_b[i][i-1]=H_b[i][i]=1 for i>=1.
    uint8_t p[56];
    p[0] = r[0];
    for (int i = 1; i < 56; ++i)
        p[i] = r[i] ^ p[i - 1];

    std::array<uint8_t, 112> codeword;
    for (int i = 0; i < 56; ++i) codeword[i]      = s[i];
    for (int i = 0; i < 56; ++i) codeword[56 + i] = p[i];
    return codeword;
}
